-- 单位: s
            function is_ev(play_time, duration) 
                local res = 0;
                if (duration < colossus_seq_ev_threshold) then
                    res  = (play_time >= colossus_seq_ev_threshold);
                elseif (duration > colossus_seq_lv_threshold) then
                    res = (play_time >= colossus_seq_lv_threshold);
                else
                    res = (play_time >= duration);
                end
                return res;
            end

            function is_lv(play_time, duration)
                local res = 0;
                if (duration < colossus_seq_inev_threshold) then
                    res = (play_time >= colossus_seq_lv_threshold);
                elseif (duration > colossus_seq_very_lv_threshold) then
                    res = (play_time >= colossus_seq_very_lv_threshold);
                else
                    res = ((33 * play_time) >= (duration * 28 + 180));
                end
                return res;
            end

            function calculate()
                if filter_func == 'filter_ev' then
                    return is_ev(play_time, duration);
                    end
                if filter_func == 'filter_lv' then
                    return is_lv(play_time, duration);
                end
                return 0;
            end

